CREATE OR REPLACE FUNCTION public.aplicar_delta_bancario(p_conta text, p_delta numeric) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE alvo uuid; BEGIN IF p_delta = 0 OR nullif(trim(p_conta),'') IS NULL THEN RETURN; END IF; SELECT id INTO alvo FROM public.saldos_bancarios WHERE lower(trim(conta))=lower(trim(p_conta)) ORDER BY data_saldo DESC, updated_at DESC, id LIMIT 1 FOR UPDATE; IF alvo IS NULL THEN RAISE EXCEPTION 'Conta bancária não cadastrada: %. Cadastre a conta antes de registrar a movimentação.', p_conta; END IF; UPDATE public.saldos_bancarios SET saldo=saldo+p_delta, data_saldo=(now() AT TIME ZONE 'America/Sao_Paulo')::date, updated_at=now() WHERE id=alvo; END; $$;
REVOKE ALL ON FUNCTION public.aplicar_delta_bancario(text,numeric) FROM PUBLIC, anon, authenticated;
CREATE OR REPLACE FUNCTION public.sincronizar_saldo_movimento() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE anterior jsonb; atual jsonb; va numeric:=0; vn numeric:=0; ca text; cn text; BEGIN IF TG_OP <> 'INSERT' THEN anterior:=to_jsonb(OLD); ca:=anterior->>'conta_bancaria'; IF lower(anterior->>'status') IN ('pago','pago_parcial') THEN IF TG_TABLE_NAME='contas' THEN va:=coalesce((anterior->>'valor_pago')::numeric,0); IF va=0 THEN va:=greatest(0,(anterior->>'valor')::numeric+coalesce((anterior->>'valor_juros')::numeric,0)-coalesce((anterior->>'valor_desconto')::numeric,0)); END IF; IF anterior->>'tipo'<>'receber' THEN va:=-va; END IF; ELSE va:=(anterior->>'valor')::numeric; IF lower(anterior->>'tipo_fluxo') NOT IN ('receita','entrada') THEN va:=-va; END IF; END IF; END IF; END IF;
IF TG_OP <> 'DELETE' THEN atual:=to_jsonb(NEW); cn:=atual->>'conta_bancaria'; IF lower(atual->>'status') IN ('pago','pago_parcial') THEN IF TG_TABLE_NAME='contas' THEN vn:=coalesce((atual->>'valor_pago')::numeric,0); IF vn=0 THEN vn:=greatest(0,(atual->>'valor')::numeric+coalesce((atual->>'valor_juros')::numeric,0)-coalesce((atual->>'valor_desconto')::numeric,0)); END IF; IF atual->>'tipo'<>'receber' THEN vn:=-vn; END IF; ELSE vn:=(atual->>'valor')::numeric; IF lower(atual->>'tipo_fluxo') NOT IN ('receita','entrada') THEN vn:=-vn; END IF; END IF; IF NEW.data_pagamento IS NULL THEN NEW.data_pagamento:=(now() AT TIME ZONE 'America/Sao_Paulo')::date; END IF; END IF; END IF;
IF lower(trim(coalesce(ca,'')))=lower(trim(coalesce(cn,''))) THEN PERFORM public.aplicar_delta_bancario(cn,vn-va); ELSE PERFORM public.aplicar_delta_bancario(ca,-va); PERFORM public.aplicar_delta_bancario(cn,vn); END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.sincronizar_saldo_movimento() FROM PUBLIC, anon, authenticated;
CREATE TRIGGER trg_saldo_movimento BEFORE INSERT OR UPDATE OR DELETE ON public.contas FOR EACH ROW EXECUTE FUNCTION public.sincronizar_saldo_movimento();
CREATE TRIGGER trg_saldo_movimento BEFORE INSERT OR UPDATE OR DELETE ON public.lancamentos_financeiros FOR EACH ROW EXECUTE FUNCTION public.sincronizar_saldo_movimento();